import{_ as a,c as n,o as r,ag as t}from"./chunks/framework.ARG558ZT.js";const m=JSON.parse('{"title":"Computer science foundations","description":"","frontmatter":{},"headers":[],"relativePath":"cs-foundations/index.md","filePath":"cs-foundations/index.md"}'),i={name:"cs-foundations/index.md"};function o(s,e,d,c,l,p){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="computer-science-foundations" tabindex="-1">Computer science foundations <a class="header-anchor" href="#computer-science-foundations" aria-label="Permalink to “Computer science foundations”">​</a></h1><p>The core target is to choose a representation, implement a small algorithm, explain <strong>why it is correct</strong>, and account for its time and storage. JavaScript functions, arrays/objects, loops, references and basic TypeScript types are sufficient prerequisites; a framework, database or completed Node service is not required.</p><h2 id="recommended-reading-order" tabindex="-1">Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to “Recommended reading order”">​</a></h2><ol><li><a href="./complexity-and-cost.html">Complexity and cost models</a>: define input sizes and distinguish worst, expected and amortized costs.</li><li><a href="./reasoning-and-recursion.html">Correctness, iteration and recursion</a>: contracts, invariants, progress and counterexamples.</li><li><a href="./data-structures.html">Data structures</a>: arrays/maps/sets, stacks/FIFO/deques, linked nodes and ownership.</li><li><a href="./binary-search.html">Binary search</a>: a complete half-open interval proof and boundary trace.</li><li><a href="./sorting.html">Sorting and quicksort</a>: partition correctness, comparator/stability policy and allocation costs.</li><li><a href="./trees-graphs-traversal.html">Trees, graphs and traversal</a>: representation, BFS/DFS/inorder and their different guarantees.</li><li><a href="./priority-queues.html">Priority queues</a>: heap invariants and a bounded local scheduler.</li></ol><p>The <a href="./coverage-map.html">coverage map</a> reconciles the existing hub sources, prerequisites, depth, examples and practice, including runtime/network/database continuations. It distinguishes what was retained from what was expanded or added. The old Big O/quicksort URLs remain compatibility pages.</p><h2 id="worked-sources-and-independent-practice" tabindex="-1">Worked sources and independent practice <a class="header-anchor" href="#worked-sources-and-independent-practice" aria-label="Permalink to “Worked sources and independent practice”">​</a></h2><p>The <a href="./../workbench/cs-foundations/">CS workbench</a> holds the canonical implementation collection and repeatable reference checks. Short explanatory code remains in these notes; larger sources are included directly so there is one owner.</p><p>The <a href="./../practice/cs-foundations/">CS-P01–06 practice sequence</a> reuses existing exercises and adds only the missing boundaries, queue and scheduler checkpoints. It can grow into one small in-memory note dependency explorer. Every learner exercise remains <strong>still required</strong>; executing supplied reference checks is not independent completion.</p><h2 id="systems-continuations-and-optional-depth" tabindex="-1">Systems continuations and optional depth <a class="header-anchor" href="#systems-continuations-and-optional-depth" aria-label="Permalink to “Systems continuations and optional depth”">​</a></h2><p>Use the <a href="./../node-js/">Node.js course</a> for event-loop/concurrency, bytes/streams, network failures, database transactions and service resource ownership. Those explanations remain in their completed organization. Begin them when the corresponding application boundary is needed, rather than copying them into CS notes.</p><p>Balanced-tree/general linked-list implementations, topological sorting, weighted shortest paths, advanced dynamic programming, OS memory/scheduling and consensus are optional further depth. The essential course does not require competitive-programming breadth or several interchangeable frameworks.</p>',11)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
